 * A failure that carries its own exit code, so the CLI entry point can
 * report it on standard error and stop without printing anything to
 * standard output.
 */
export class CliError extends Error {
  constructor(message, exitCode) {
    super(message)
    this.exitCode = exitCode
  }
}

/** A regular failure: one line on stderr, exit code 2. */
export class UsageError extends CliError {
  constructor(message) {
    super(message, 2)
  }
}

/** A cycle in the build graph: exit code 3. */
export class CycleError extends CliError {
  constructor(names) {
    super(`error: cycle: ${names.join(' -> ')}`, 3)
  }
}
"}

