{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-NSmb2C/src/parse.js","content":"import { UsageError } from './errors.js'

const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^[0-9]+$/

/**
 * Parse a build graph out of the raw text read from standard input.
 *
 * Returns a map from task name to `{ name, cost, deps }`, where `deps` is
 * a `Set` of dependency names in ascending order of first mention (order
 * does not matter for correctness, only that duplicates collapse).
 *
 * Throws `UsageError` for every malformed-input case the specification
 * describes, each carrying the message it prescribes.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  // Each entry: { subjectName, subjectLine, deps: [names in listed order] }
  const depDirectives = []

  for (let i = 0; i < lines.length; i += 1) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new UsageError(`error: line ${lineNumber}: expected task <name> <cost>`)
      }
      const [, name, costText] = words
      if (!NAME_PATTERN.test(name)) {
        throw new UsageError(`error: line ${lineNumber}: invalid task name ${name}`)
      }
      if (!COST_PATTERN.test(costText)) {
        throw new UsageError(`error: line ${lineNumber}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new UsageError(`error: line ${lineNumber}: task ${name} is declared twice`)
      }
      tasks.set(name, { name, cost: Number(costText), deps: new Set() })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new UsageError(`error: line ${lineNumber}: expected dep <name> <dependency>...`)
      }
      const [, subject, ...deps] = words
      depDirectives.push({ subject, deps })
    } else {
      throw new UsageError(`error: line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  for (const { subject, deps } of depDirectives) {
    if (!tasks.has(subject)) throw new UsageError(`error: unknown task ${subject}`)
    for (const dep of deps) {
      if (!tasks.has(dep)) throw new UsageError(`error: unknown task ${dep}`)
    }
  }

  for (const { subject, deps } of depDirectives) {
    const task = tasks.get(subject)
    for (const dep of deps) task.deps.add(dep)
  }

  return tasks
}
"}

