{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T011142Z/cell-NSmb2C/src/graph.js","content":"import { CycleError } from './errors.js'

/**
 * Find a cycle, if one exists, using a depth-first search that starts
 * from each task in ascending name order and walks each task's
 * dependencies in ascending name order. Throws `CycleError` for the
 * first cycle such a search re-enters.
 *
 * `tasks` is the map produced by `parseGraph`.
 */
export function detectCycle(tasks) {
  const WHITE = 0
  const GRAY = 1
  const BLACK = 2
  const color = new Map()
  for (const name of tasks.keys()) color.set(name, WHITE)

  const names = [...tasks.keys()].sort()
  const stack = []

  function visit(name) {
    color.set(name, GRAY)
    stack.push(name)
    const deps = [...tasks.get(name).deps].sort()
    for (const dep of deps) {
      const state = color.get(dep)
      if (state === GRAY) {
        const start = stack.indexOf(dep)
        const cycle = stack.slice(start)
        cycle.push(dep)
        throw new CycleError(cycle)
      }
      if (state === WHITE) visit(dep)
    }
    color.set(name, BLACK)
    stack.pop()
  }

  for (const name of names) {
    if (color.get(name) === WHITE) visit(name)
  }
}

/**
 * Compute each task's start, finish and depth (its wave index), assuming
 * unlimited workers. `tasks` must already be known to be acyclic.
 *
 * Returns a map from name to `{ start, finish, depth }`.
 */
export function computeTimings(tasks) {
  const timings = new Map()

  function compute(name) {
    if (timings.has(name)) return timings.get(name)
    const task = tasks.get(name)
    let start = 0
    let depth = 0
    for (const dep of task.deps) {
      const depTiming = compute(dep)
      if (depTiming.finish > start) start = depTiming.finish
      if (depTiming.depth + 1 > depth) depth = depTiming.depth + 1
    }
    const finish = start + task.cost
    const timing = { start, finish, depth }
    timings.set(name, timing)
    return timing
  }

  for (const name of tasks.keys()) compute(name)
  return timings
}

/**
 * Compute each task's scheduling priority: the cost of the longest chain
 * of dependents starting at it, counting its own cost and then the
 * costs of every task down to one that nothing depends on.
 */
export function computePriorities(tasks) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const task of tasks.values()) {
    for (const dep of task.deps) dependents.get(dep).push(task.name)
  }

  const priorities = new Map()

  function compute(name) {
    if (priorities.has(name)) return priorities.get(name)
    const task = tasks.get(name)
    let best = 0
    for (const child of dependents.get(name)) {
      const childPriority = compute(child)
      if (childPriority > best) best = childPriority
    }
    const priority = task.cost + best
    priorities.set(name, priority)
    return priority
  }

  for (const name of tasks.keys()) compute(name)
  return priorities
}
"}

