/**
 * Simulate the build graph on `workerCount` workers, as described in the
 * specification: at every instant, while a worker is free and some task
 * is ready, the ready task with the greatest priority (ties broken by
 * ascending name) starts on the free worker with the smallest index.
 *
 * Returns `{ assignments, makespan }`, where `assignments` is an array
 * indexed by worker, each holding the ordered list of
 * `{ name, start, finish }` it ran.
 */
export function packSchedule(tasks, workerCount) {
  const priorities = computePriorities(tasks)
  const freeAt = new Array(workerCount).fill(0)
  const assignments = Array.from({ length: workerCount }, () => [])
  const finishOf = new Map()
  const remaining = new Set(tasks.keys())

  let time = 0
  let makespan = 0

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let worker = -1
      for (let i = 0; i < workerCount; i += 1) {
        if (freeAt[i] <= time) {
          worker = i
          break
        }
      }
      if (worker === -1) break

      let best = null
      for (const name of remaining) {
        const task = tasks.get(name)
        let ready = true
        for (const dep of task.deps) {
          if ((finishOf.get(dep) ?? Infinity) > time) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (
          best === null ||
          priorities.get(name) > priorities.get(best) ||
          (priorities.get(name) === priorities.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const task = tasks.get(best)
      const start = time
      const finish = start + task.cost
      assignments[worker].push({ name: best, start, finish })
      freeAt[worker] = finish
      finishOf.set(best, finish)
      remaining.delete(best)
      if (finish > makespan) makespan = finish
      progressed = true
    }

    if (remaining.size > 0) {
      let next = Infinity
      for (let i = 0; i < workerCount; i += 1) {
        if (freeAt[i] > time && freeAt[i] < next) next = freeAt[i]
      }
      time = next
    }
  }

  return { assignments, makespan }
}
"}

