/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'
import { CliError, UsageError } from './errors.js'
import { parseGraph } from './parse.js'
import { detectCycle, computeTimings } from './graph.js'
import { packSchedule } from './pack.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_PATTERN = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_PATTERN.test(argv[1])) {
      throw new UsageError('error: workers must be a positive integer')
    }
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw new UsageError(USAGE)
}

function runWaves(tasks) {
  const timings = computeTimings(tasks)
  let maxDepth = -1
  let total = 0
  for (const { depth, finish } of timings.values()) {
    if (depth > maxDepth) maxDepth = depth
    if (finish > total) total = finish
  }

  const lines = []
  for (let depth = 0; depth <= maxDepth; depth += 1) {
    const names = [...tasks.keys()].filter((name) => timings.get(name).depth === depth).sort()
    lines.push(`wave ${depth}: ${names.join(' ')}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runExplain(tasks) {
  const timings = computeTimings(tasks)
  let total = 0
  for (const { finish } of timings.values()) {
    if (finish > total) total = finish
  }

  const lines = []
  for (const name of [...tasks.keys()].sort()) {
    const { start, finish, depth } = timings.get(name)
    lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runPack(tasks, workers) {
  const { assignments, makespan } = packSchedule(tasks, workers)
  const lines = []
  for (let i = 0; i < workers; i += 1) {
    const runs = assignments[i].map(({ name, start, finish }) => ` ${name}@${start}-${finish}`).join('')
    lines.push(`worker ${i}:${runs}`)
  }
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const args = parseArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')
  const tasks = parseGraph(input)
  detectCycle(tasks)

  if (args.mode === 'waves') return runWaves(tasks)
  if (args.mode === 'explain') return runExplain(tasks)
  return runPack(tasks, args.workers)
}

try {
  const output = main()
  process.stdout.write(output)
} catch (error) {
  if (error instanceof CliError) {
    process.stderr.write(error.message + '\n')
    process.exit(error.exitCode)
  }
  throw error
}
"}

